/**
 * GitHub 同步状态 Hook
 * 管理各模块的"未同步"标记，以及提供通用同步函数
 */

import { useState, useCallback, useRef, useEffect } from 'react';
import { scopedStorage, logger } from '@lark-apaas/client-toolkit-lite';
import { toast } from 'sonner';
import {
  createOrUpdateFile,
  getFileContent,
  decodeBase64Content,
  type GithubConfig,
} from '@/lib/github-api';

const SYNC_STATUS_KEY = '__app_ledlight_sync_status_v1';

export type SyncModuleKey =
  | 'products'
  | 'advantages'
  | 'testimonials'
  | 'features'
  | 'heroSlides'
  | 'about'
  | 'news'
  | 'footer'
  | 'seo'
  | 'categories'
  | 'privacy';

export interface SyncStatusMap {
  [key: string]: 'synced' | 'dirty' | 'syncing' | 'error';
}

const DEFAULT_STATUS: SyncStatusMap = {
  products: 'synced',
  advantages: 'synced',
  testimonials: 'synced',
  features: 'synced',
  heroSlides: 'synced',
  about: 'synced',
  news: 'synced',
  footer: 'synced',
  seo: 'synced',
  categories: 'synced',
  privacy: 'synced',
};

function loadSyncStatus(): SyncStatusMap {
  try {
    const saved = scopedStorage.getItem(SYNC_STATUS_KEY);
    if (saved) {
      return { ...DEFAULT_STATUS, ...JSON.parse(saved) };
    }
  } catch {
    // ignore
  }
  return { ...DEFAULT_STATUS };
}

function saveSyncStatus(status: SyncStatusMap) {
  try {
    scopedStorage.setItem(SYNC_STATUS_KEY, JSON.stringify(status));
  } catch {
    // ignore
  }
}

/**
 * 生成图片文件名：时间戳 + 随机字符串
 */
export function generateImageFilename(originalName: string, moduleDir: string): string {
  const ext = originalName.split('.').pop()?.toLowerCase() || 'jpg';
  const safeExt = ['jpg', 'jpeg', 'png', 'webp', 'gif'].includes(ext) ? ext : 'jpg';
  const timestamp = Date.now();
  const random = Math.random().toString(36).slice(2, 8);
  return `images/custom/${moduleDir}/${timestamp}_${random}.${safeExt}`;
}

/**
 * 从 base64 DataURL 提取纯 base64 内容和 MIME 类型
 */
export function extractBase64FromDataUrl(dataUrl: string): { base64: string; mimeType: string } {
  const match = dataUrl.match(/^data:([^;]+);base64,(.+)$/);
  if (!match) {
    return { base64: dataUrl, mimeType: 'image/jpeg' };
  }
  return { mimeType: match[1], base64: match[2] };
}

/**
 * 判断图片路径是否是本地上传的 base64（需要同步）
 */
export function isLocalBase64Image(path: string): boolean {
  return typeof path === 'string' && path.startsWith('data:image/');
}

/**
 * 同步单个 JSON 数据文件到 GitHub
 */
export async function syncJsonData(
  config: GithubConfig,
  dataPath: string,
  data: unknown,
  moduleName: string
): Promise<{ success: boolean; commitSha?: string }> {
  const jsonStr = JSON.stringify(data, null, 2);
  const result = await createOrUpdateFile(
    config,
    dataPath,
    jsonStr,
    `Update ${moduleName} data via admin panel`,
    false
  );
  return { success: result.success, commitSha: result.commit.sha };
}

/**
 * 同步单个图片到 GitHub
 * 返回仓库内的图片路径（如 images/custom/products/xxx.jpg）
 */
export async function syncImage(
  config: GithubConfig,
  dataUrl: string,
  targetPath: string
): Promise<{ success: boolean; path: string }> {
  const { base64 } = extractBase64FromDataUrl(dataUrl);
  await createOrUpdateFile(
    config,
    targetPath,
    base64,
    `Upload image: ${targetPath}`,
    true
  );
  return { success: true, path: targetPath };
}

/**
 * 使用 Hook：同步状态管理
 */
export function useSyncStatus() {
  const [statusMap, setStatusMap] = useState<SyncStatusMap>(loadSyncStatus);
  const initializedRef = useRef(false);

  useEffect(() => {
    if (!initializedRef.current) {
      initializedRef.current = true;
      return;
    }
    saveSyncStatus(statusMap);
  }, [statusMap]);

  const markDirty = useCallback((module: SyncModuleKey) => {
    setStatusMap((prev) => ({ ...prev, [module]: 'dirty' }));
  }, []);

  const markSynced = useCallback((module: SyncModuleKey) => {
    setStatusMap((prev) => ({ ...prev, [module]: 'synced' }));
  }, []);

  const markSyncing = useCallback((module: SyncModuleKey) => {
    setStatusMap((prev) => ({ ...prev, [module]: 'syncing' }));
  }, []);

  const markError = useCallback((module: SyncModuleKey) => {
    setStatusMap((prev) => ({ ...prev, [module]: 'error' }));
  }, []);

  const getStatus = useCallback(
    (module: SyncModuleKey) => statusMap[module] || 'synced',
    [statusMap]
  );

  const isDirty = useCallback(
    (module: SyncModuleKey) => statusMap[module] === 'dirty',
    [statusMap]
  );

  const dirtyModules = Object.entries(statusMap)
    .filter(([, v]) => v === 'dirty')
    .map(([k]) => k);

  return {
    statusMap,
    markDirty,
    markSynced,
    markSyncing,
    markError,
    getStatus,
    isDirty,
    dirtyModules,
  };
}

/**
 * 通用同步包装：执行同步并显示 toast 进度
 */
export async function performSync(
  syncFn: () => Promise<void>,
  moduleLabel: string
): Promise<boolean> {
  const loadingToast = toast.loading(`Syncing ${moduleLabel}...`);
  try {
    await syncFn();
    toast.success(`${moduleLabel} synced successfully`, { id: loadingToast });
    return true;
  } catch (err) {
    const msg = err instanceof Error ? err.message : 'Unknown error';
    toast.error(`Sync failed: ${msg}`, { id: loadingToast });
    logger.error(`Sync ${moduleLabel} failed:`, String(err));
    return false;
  }
}

/**
 * 从 GitHub 获取 JSON 数据（前台用，带缓存和回退）
 */
export async function fetchRemoteJson<T>(
  config: GithubConfig | null,
  path: string,
  fallback: T
): Promise<{ data: T; source: 'remote' | 'fallback' }> {
  if (!config) {
    return { data: fallback, source: 'fallback' };
  }

  try {
    const file = await getFileContent(config, path);
    if (!file || !file.content) {
      return { data: fallback, source: 'fallback' };
    }
    const decoded = decodeBase64Content(file.content);
    const parsed = JSON.parse(decoded) as T;
    return { data: parsed, source: 'remote' };
  } catch (err) {
    logger.warn(`Failed to fetch remote data ${path}:`, String(err));
    return { data: fallback, source: 'fallback' };
  }
}
